import anchorsJson from "@/public/pixel/tree-anchors.json";
import { branches, getBranchForCategory } from "@/content/branches";
import type { AppleKind, TreeProject } from "@/lib/tree/types";

/** Tree sprite size in art pixels (generated by scripts/pixel/build.mjs). */
export const TREE_W = anchorsJson.width;
export const TREE_H = anchorsJson.height;
/** Apple sprite size in art pixels. */
export const APPLE_PX = 12;
/** Wooden sign plank size in art pixels (planks are baked into tree.png). */
export const SIGN_W = anchorsJson.sign.w;
export const SIGN_H = anchorsJson.sign.h;
/** Ground strip height in art pixels, and how far the roots sink into it. */
export const GROUND_H = 14;
export const GROUND_OVERLAP = 2;
/** Full stage height in art pixels (tree + ground, minus overlap). */
export const STAGE_H = TREE_H + GROUND_H - GROUND_OVERLAP;

export type ApplePlacement = {
  slug: string;
  branch: string;
  kind: AppleKind;
  /** Top-left of the 12×12 sprite, in art px relative to the tree sprite. */
  x: number;
  y: number;
  /** Deterministic sway phase (radians). */
  phase: number;
};

export type SignPlacement = {
  id: string;
  label: string;
  side: "left" | "right";
  /** Top-left of the plank in art px relative to the tree sprite. */
  x: number;
  y: number;
};

type Slot = { x: number; y: number };
const branchSlots = anchorsJson.slots as Record<string, Slot[]>;

function hash(text: string) {
  let h = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export function branchIdFor(project: Pick<TreeProject, "category" | "tree">) {
  return project.tree?.branch ?? getBranchForCategory(project.category).id;
}

/**
 * Where each apple hangs. Each branch has apple slots computed from the tree art
 * (under that branch's own leaves, spread apart). Projects fill their branch's
 * slots oldest-first, so adding a new project never moves an existing apple. If
 * a branch ever runs out of slots, extra apples hang just beside the last one.
 */
export function placeApples(projects: TreeProject[]): ApplePlacement[] {
  const byBranch = new Map<string, TreeProject[]>();
  for (const project of projects) {
    const branch = branchIdFor(project);
    const list = byBranch.get(branch) ?? [];
    list.push(project);
    byBranch.set(branch, list);
  }

  const placements: ApplePlacement[] = [];
  for (const [branch, list] of byBranch) {
    const slots = branchSlots[branch] ?? branchSlots.hackathons ?? [];
    const ordered = [...list].sort(
      (a, b) =>
        a.year - b.year ||
        (a.date ?? "").localeCompare(b.date ?? "") ||
        a.slug.localeCompare(b.slug),
    );
    ordered.forEach((project, index) => {
      const slot =
        slots[index] ??
        (() => {
          const last = slots[slots.length - 1] ?? { x: TREE_W / 2, y: TREE_H * 0.4 };
          const extra = index - slots.length + 1;
          return { x: last.x + (extra % 2 ? -1 : 1) * APPLE_PX * Math.ceil(extra / 2), y: last.y + 4 };
        })();
      placements.push({
        slug: project.slug,
        branch,
        kind: project.apple,
        x: slot.x,
        y: slot.y,
        phase: (hash(project.slug) % 628) / 100,
      });
    });
  }
  return placements;
}

/** Sign planks (baked into tree.png); the DOM lays the readable label over each. */
export function placeSigns(): SignPlacement[] {
  return (anchorsJson.signs as { id: string; side: "left" | "right"; x: number; y: number }[]).map(
    (sign) => ({
      id: sign.id,
      label: branches.find((b) => b.id === sign.id)?.shortLabel ?? sign.id,
      side: sign.side,
      x: sign.x,
      y: sign.y,
    }),
  );
}

/**
 * Whole art-px scale for the stage: the site unit (4 desktop / 3 phone), reduced
 * so the full tree fits the available width, never below 2.
 */
export function stageUnit(preferred: number, hostWidth: number): number {
  return Math.max(2, Math.min(preferred, Math.floor(hostWidth / TREE_W)));
}

/** Scene frame-swap interval per project, from project-visual-mapping.md. */
export const SCENE_LOOP_MS: Record<string, number> = {
  vision: 900,
  mira: 700,
  radar: 800,
  larpcity: 800,
  carbonlens: 900,
  "datafest-2026": 1000,
  stochastic: 800,
  leanify: 900,
  "vending-machine-robot": 600,
  "portfolio-website": 1000,
};

export function sceneFrames(slug: string): [string, string] {
  return [`/pixel/scene-${slug}-f0.png`, `/pixel/scene-${slug}-f1.png`];
}
